package com.arqly.backend.service;
import com.arqly.backend.activity.ActivityEventPublisher;import com.arqly.backend.dto.FinancialDtos.*;import com.arqly.backend.entity.*;import com.arqly.backend.exception.*;import com.arqly.backend.repository.*;import java.math.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class FinancialService { private final FinancialEntryRepository entries;private final FinancialInstallmentRepository installments;private final FinancialSettlementRepository settlements;private final FinancialCategoryRepository categories;private final TenantUserRepository users;private final ClientRepository clients;private final ProjectRepository projects;private final ActivityEventPublisher activities;
 public FinancialService(FinancialEntryRepository e,FinancialInstallmentRepository i,FinancialSettlementRepository s,FinancialCategoryRepository c,TenantUserRepository u,ClientRepository cl,ProjectRepository p,ActivityEventPublisher a){entries=e;installments=i;settlements=s;categories=c;users=u;clients=cl;projects=p;activities=a;}
 @Transactional public EntryResponse create(UUID tenant,UUID user,EntryRequest r){var author=users.findByIdAndTenantId(user,tenant).orElseThrow(()->new NotFoundException("Usuário não encontrado."));var e=new FinancialEntry();e.setTenant(author.getTenant());e.setCreatedBy(author);e.setType(r.type());e.setDescription(r.description());e.setTotalAmount(r.totalAmount().setScale(2,RoundingMode.HALF_UP));e.setIssueDate(r.issueDate());e.setCompetenceDate(r.competenceDate());e.setCounterpartyName(r.counterpartyName());e.setNotes(r.notes());e.setClientVisible(r.clientVisible());e.setClient(r.clientId()==null?null:clients.findByIdAndTenantIdAndDeletedFalse(r.clientId(),tenant).orElseThrow(()->new NotFoundException("Cliente não encontrado.")));e.setProject(r.projectId()==null?null:projects.findByIdAndTenantIdAndDeletedFalse(r.projectId(),tenant).orElseThrow(()->new NotFoundException("Projeto não encontrado.")));if(e.getProject()!=null&&e.getClient()==null)e.setClient(e.getProject().getClient());e.setCategory(r.categoryId()==null?null:categories.findByIdAndTenantId(r.categoryId(),tenant).orElseThrow(()->new NotFoundException("Categoria não encontrada.")));entries.save(e);generate(e,r.installmentCount(),r.firstDueDate(),r.periodicity());activity(e,user,author.getName(),ActivityType.FINANCIAL_ENTRY_CREATED,"Lançamento financeiro criado");return response(e);}
 @Transactional public SettlementResponse settle(UUID tenant,UUID user,UUID id,SettlementRequest r){var i=installments.findByIdAndEntryTenantIdAndEntryDeletedFalse(id,tenant).orElseThrow(()->new NotFoundException("Parcela não encontrada."));if(i.getStatus()==FinancialInstallmentStatus.CANCELLED)throw new BusinessException("Parcela cancelada.");var balance=i.getAmount().subtract(i.getSettledAmount());if(r.amount().compareTo(balance)>0)throw new BusinessException("O valor da baixa não pode ser maior que o saldo da parcela.");var s=new FinancialSettlement();s.setInstallment(i);s.setAmount(r.amount());s.setSettlementDate(r.settlementDate());s.setPaymentMethod(r.paymentMethod());s.setDescription(r.description());var actor=users.findByIdAndTenantId(user,tenant).orElseThrow();s.setCreatedBy(actor);settlements.save(s);recalculate(i);activity(i.getEntry(),user,actor.getName(),i.getStatus()==FinancialInstallmentStatus.PAID?ActivityType.FINANCIAL_SETTLED:ActivityType.FINANCIAL_PARTIAL_SETTLEMENT,i.getStatus()==FinancialInstallmentStatus.PAID?"Parcela liquidada":"Baixa parcial registrada");return new SettlementResponse(s.getId(),s.getAmount(),s.getSettlementDate(),s.getPaymentMethod(),s.getDescription(),false);}
 @Transactional public void reverse(UUID tenant,UUID user,UUID id,String reason){if(reason==null||reason.isBlank())throw new BusinessException("Informe o motivo do estorno.");var s=settlements.findByIdAndInstallmentEntryTenantId(id,tenant).orElseThrow(()->new NotFoundException("Liquidação não encontrada."));if(s.getReversedAt()!=null)throw new BusinessException("Liquidação já estornada.");var actor=users.findByIdAndTenantId(user,tenant).orElseThrow();s.setReversedAt(Instant.now());s.setReversalReason(reason);s.setReversedBy(actor);recalculate(s.getInstallment());activity(s.getInstallment().getEntry(),user,actor.getName(),ActivityType.FINANCIAL_SETTLEMENT_REVERSED,"Baixa estornada");}
 @Transactional public void cancel(UUID tenant,UUID user,UUID id){var e=entries.findByIdAndTenantIdAndDeletedFalse(id,tenant).orElseThrow(()->new NotFoundException("Lançamento não encontrado."));if(installments.findAllByEntryIdOrderByInstallmentNumber(id).stream().anyMatch(i->i.getSettledAmount().signum()>0))throw new BusinessException("Uma conta com pagamentos registrados não pode ser cancelada diretamente. Estorne as baixas primeiro.");e.setStatus(FinancialEntryStatus.CANCELLED);installments.findAllByEntryIdOrderByInstallmentNumber(id).forEach(i->i.setStatus(FinancialInstallmentStatus.CANCELLED));var actor=users.findByIdAndTenantId(user,tenant).orElseThrow();activity(e,user,actor.getName(),ActivityType.FINANCIAL_ENTRY_CANCELLED,"Lançamento cancelado");}
 @Transactional public CategoryResponse category(UUID tenant,UUID user,CategoryRequest r){var c=new FinancialCategory();c.setTenant(users.findByIdAndTenantId(user,tenant).orElseThrow().getTenant());c.setName(r.name());c.setType(r.type());c.setActive(r.active());categories.save(c);return new CategoryResponse(c.getId(),c.getName(),c.getType(),c.isActive());}
 @Transactional(readOnly=true)public List<EntryResponse> list(UUID t,FinancialEntryType type){return entries.findAllByTenantIdAndDeletedFalseOrderByCreatedAtDesc(t).stream().filter(e->type==null||e.getType()==type).map(this::response).toList();}@Transactional(readOnly=true)public EntryResponse get(UUID t,UUID id){return response(entries.findByIdAndTenantIdAndDeletedFalse(id,t).orElseThrow(()->new NotFoundException("Lançamento não encontrado.")));}@Transactional(readOnly=true)public CashFlowResponse cashFlow(UUID t){var l=list(t,null);return new CashFlowResponse(sum(l,FinancialEntryType.RECEIVABLE,false),sum(l,FinancialEntryType.PAYABLE,false),sum(l,FinancialEntryType.RECEIVABLE,true),sum(l,FinancialEntryType.PAYABLE,true),sum(l,FinancialEntryType.RECEIVABLE,false).subtract(sum(l,FinancialEntryType.PAYABLE,false)),sum(l,FinancialEntryType.RECEIVABLE,true).subtract(sum(l,FinancialEntryType.PAYABLE,true)));}@Transactional(readOnly=true)public List<CategoryResponse> categories(UUID t){return categories.findAllByTenantIdOrderByNameAsc(t).stream().map(c->new CategoryResponse(c.getId(),c.getName(),c.getType(),c.isActive())).toList();}
 private void generate(FinancialEntry e,int n,LocalDate first,FinancialPeriodicity p){var base=e.getTotalAmount().divide(BigDecimal.valueOf(n),2,RoundingMode.DOWN);for(int x=1;x<=n;x++){var i=new FinancialInstallment();i.setEntry(e);i.setInstallmentNumber(x);i.setDescription(e.getDescription()+" — "+x+"/"+n);i.setAmount(x==n?e.getTotalAmount().subtract(base.multiply(BigDecimal.valueOf(n-1))):base);i.setDueDate(p==FinancialPeriodicity.WEEKLY?first.plusWeeks(x-1):first.plusMonths(x-1));installments.save(i);}}private void recalculate(FinancialInstallment i){var paid=settlements.findAllByInstallmentIdOrderBySettlementDateAsc(i.getId()).stream().filter(s->s.getReversedAt()==null).map(FinancialSettlement::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);i.setSettledAmount(paid);i.setStatus(paid.signum()==0?FinancialInstallmentStatus.OPEN:paid.compareTo(i.getAmount())>=0?FinancialInstallmentStatus.PAID:FinancialInstallmentStatus.PARTIALLY_PAID);var all=installments.findAllByEntryIdOrderByInstallmentNumber(i.getEntry().getId());i.getEntry().setStatus(all.stream().allMatch(x->x.getStatus()==FinancialInstallmentStatus.PAID)?FinancialEntryStatus.SETTLED:all.stream().anyMatch(x->x.getSettledAmount().signum()>0)?FinancialEntryStatus.PARTIALLY_SETTLED:FinancialEntryStatus.OPEN);}private EntryResponse response(FinancialEntry e){var l=installments.findAllByEntryIdOrderByInstallmentNumber(e.getId()).stream().map(i->new InstallmentResponse(i.getId(),i.getInstallmentNumber(),i.getDescription(),i.getAmount(),i.getSettledAmount(),i.getAmount().subtract(i.getSettledAmount()),i.getDueDate(),i.getStatus().name(),i.getStatus()!=FinancialInstallmentStatus.PAID&&i.getStatus()!=FinancialInstallmentStatus.CANCELLED&&i.getDueDate().isBefore(LocalDate.now()))).toList();var paid=l.stream().map(InstallmentResponse::settledAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return new EntryResponse(e.getId(),e.getType(),e.getDescription(),e.getClient()==null?null:e.getClient().getName(),e.getProject()==null?null:e.getProject().getName(),e.getCategory()==null?null:e.getCategory().getName(),e.getTotalAmount(),paid,e.getTotalAmount().subtract(paid),e.getStatus(),e.getIssueDate(),e.isClientVisible(),l);}private BigDecimal sum(List<EntryResponse> l,FinancialEntryType t,boolean paid){return l.stream().filter(e->e.type()==t&&e.status()!=FinancialEntryStatus.CANCELLED).map(e->paid?e.settledAmount():e.balance()).reduce(BigDecimal.ZERO,BigDecimal::add);}private void activity(FinancialEntry e,UUID author,String name,ActivityType type,String title){activities.publishFile(e.getTenant().getId(),e.getProject()==null?null:e.getProject().getId(),null,null,e.getProposal()==null?null:e.getProposal().getId(),e.getClient()==null?null:e.getClient().getId(),author,name,type,title,e.getDescription(),null);}}
